-- Executed on the Database Server:
CREATE TABLE employees (
    emp_id INT PRIMARY KEY,
    emp_name VARCHAR(50),
    department VARCHAR(50)
);

-- Sent from a remote Client application:
SELECT emp_name, department FROM employees WHERE department = 'AI_Research';

-- Example of Horizontal Partitioning (Distribution) across sites:
-- Site 1:
CREATE TABLE emp_north AS SELECT * FROM employees WHERE region = 'North';
-- Site 2:
CREATE TABLE emp_south AS SELECT * FROM employees WHERE region = 'South';

-- Example of Full Replication:
-- Both Site A and Site B maintain an identical copy of this table:
CREATE TABLE global_config (
    param_key VARCHAR(50) PRIMARY KEY,
    param_val VARCHAR(255)
);

-- Simulating allocation assignment tracking in a metadata catalog table
CREATE TABLE fragment_allocation (
    fragment_name VARCHAR(50),
    site_id VARCHAR(50),
    is_replica BOOLEAN
);

-- Allocating fragments to different nodes
INSERT INTO fragment_allocation VALUES ('emp_delhi', 'Site_North', FALSE);
INSERT INTO fragment_allocation VALUES ('emp_delhi', 'Site_Backup', TRUE);

SELECT * FROM fragment_allocation;

