-- Enable global database naming enforcement
ALTER SYSTEM SET GLOBAL_NAMES = TRUE;

-- Create a local synonym for a fully qualified remote object
-- This simplifies name resolution for application developers
CREATE SYNONYM emp_global FOR hr.employees@branch_db_link;

-- Query using the resolved synonym
SELECT * FROM emp_global WHERE salary > 50000;

-- Create a database link to a remote node
CREATE DATABASE LINK node_b_link CONNECT TO scott IDENTIFIED BY tiger USING 'node_b_tns';

-- Create a location-transparent view combining local and remote data
CREATE VIEW employee_global AS
SELECT emp_id, emp_name, 'Delhi' AS location FROM local_employees
UNION ALL
SELECT emp_id, emp_name, 'Mumbai' AS location FROM remote_employees@node_b_link;

-- Query without knowing where records physically live
SELECT * FROM employee_global WHERE emp_id = 101;

