code.src:
-- Conceptual XA / Distributed transaction block (supported by modern SQL engines)
BEGIN TRANSACTION;

-- Update local account
UPDATE accounts SET balance = balance - 500 WHERE account_id = 101;

-- Update remote account via database link
UPDATE remote_accounts@mumbai_db SET balance = balance + 500 WHERE account_id = 202;

-- Two-Phase Commit is automatically triggered here by the DDBMS
COMMIT;

-- Conceptual transaction flow for 2PC across distributed nodes
-- Coordinator node initiates prepare
BEGIN DISTRIBUTED TRANSACTION;
-- Node A prepare
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
-- Node B prepare
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
-- If all OK, coordinator issues commit
COMMIT;
-- If error occurs anywhere
-- ROLLBACK;

