-- Problem: Stale statistics causing bad query plan.
-- Solution: Force manual statistics refresh before complex query execution.

ANALYZE TABLE Employees ESTIMATE STATISTICS FOR ALL COLUMNS;
ANALYZE TABLE Departments ESTIMATE STATISTICS FOR ALL COLUMNS;

-- Run optimized query
SELECT /*+ INDEX(Employees idx_emp_sal) */ * 
FROM Employees 
WHERE salary > 100000;

-- Example of creating a secure user and granting restricted access in a distributed node
CREATE USER 'audit_user'@'192.168.1.%' IDENTIFIED BY 'StrongPass123!';
-- Restrict access only to local fragment data to minimize exposure
GRANT SELECT ON CompanyDB.Employee_Fragment_North TO 'audit_user'@'192.168.1.%';
FLUSH PRIVILEGES;

-- Enforcing a check constraint across a distributed table schema
CREATE TABLE Global_Inventory (
    item_id INT PRIMARY KEY,
    stock_qty INT CHECK (stock_qty >= 0),
    warehouse_loc VARCHAR(50)
);
-- If an update violates the constraint, the DDB aborts the transaction across nodes
UPDATE Global_Inventory SET stock_qty = stock_qty - 50 WHERE item_id = 101;
